<template>
  <div class="">
    <h4>系统配置</h4>
    <el-divider></el-divider>
    <el-form
      inline
      :model="ruleForm"
      :rules="rules"
      ref="ruleForm"
      label-width="130px"
      class="demo-ruleForm mt-30"
      size="small"
    >
      <el-form-item label="记录存储" prop="is_record">
        <el-switch
          v-model="ruleForm.is_record"
          :active-value="1"
          :inactive-value="0"
        ></el-switch>
      </el-form-item>
      <el-form-item label="视频录制" prop="is_record_video">
        <el-switch
          v-model="ruleForm.is_record_video"
          :active-value="1"
          :inactive-value="0"
        ></el-switch>
      </el-form-item>
      <el-form-item label="存储时间(天)" prop="save_duration">
        <el-input-number
          controls-position="right"
          v-model="ruleForm.save_duration"
          :min="1"
        ></el-input-number>
      </el-form-item>
      <el-form-item>
        <el-button type="primary" @click="submitForm('ruleForm')"
          >确 定</el-button
        >
      </el-form-item>
    </el-form>
    <h4>系统升级</h4>
    <el-divider></el-divider>
    <el-form
      inline
      :model="upgradeForm"
      :rules="rules"
      ref="upgrade"
      label-width="130px"
      class="demo-ruleForm mt-30"
      size="small"
    >
      <el-form-item label="文件(bin类型)" prop="file">
        <Upload
          :file="fileList"
          ref="Upload"
          :fileType="fileType"
          :showTip="false"
        />
      </el-form-item>

      <el-form-item>
        <el-button type="primary" @click="submitUpgradeForm('upgrade')"
          >确 定</el-button
        >
      </el-form-item>
    </el-form>
    <h4>系统重启</h4>
    <el-divider></el-divider>
    <div class="d-flex f-center">
      <div class="ml-10 f-bold fs-14">重新启动设备</div>
      <el-button type="primary" size="small" class="ml-10" @click="restart"
        >重启</el-button
      >
    </div>
  </div>
</template>

<script>
import Upload from "@/components/upload.vue";
export default {
  components: {
    Upload,
  },
  data() {
    return {
      ruleForm: {
        save_duration: 7,
        is_record: 0,
      },
      rules: {
        save_duration: [{ required: true, message: "请输入", trigger: "blur" }],
        // file: [{ required: true, message: "请选择", trigger: "change" }],
      },
      upgradeForm: {},
      fileList: [],
      fileType: ["bin"],
    };
  },
  created() {
    this.getData();
  },
  methods: {
    restart() {
      this.$confirm("是否重启系统?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          this.$api.post("/sys/restartSystem").then(() => {
            this.$message.success("操作成功");
          });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消",
          });
        });
    },
    getData() {
      this.$api.get(`/settting/getSysSetting`).then((res) => {
        if (res.data.data) {
          this.ruleForm = res.data.data;
        }
      });
    },
    submitForm(formName) {
      this.$refs[formName].validate((valid) => {
        if (valid) {
          this.$api
            .post("/settting/updateSysSetting", this.ruleForm)
            .then(() => {
              this.$message.success("操作成功");
              this.getData();
            });
        } else {
          return false;
        }
      });
    },
    submitUpgradeForm(formName) {
      this.upgradeForm.file = this.$refs.Upload.fileList[0];
      if (!this.upgradeForm.file) return this.$message.warning("请上传文件！");
      this.$refs[formName].validate((valid) => {
        if (valid) {
          let formData = new FormData();
          if (this.isFile(this.upgradeForm.file)) {
            formData.append("file", this.upgradeForm.file);
          }
          this.$api
            .post("/sys/upgradeSystem", this.upgradeForm, {
              headers: {
                "Content-Type": "multipart/form-data",
              },
            })
            .then(() => {
              this.$message.success("操作成功");
              this.getData();
            });
        } else {
          return false;
        }
      });
    },
    isFile(obj) {
      return (
        obj instanceof File ||
        (obj && typeof obj === "object" && obj.constructor.name === "File")
      );
    },
  },
};
</script>

